begin;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data,email_confirmed_at) select ('a3100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'invoice-'||n||'@example.test','{"name":"Invoice fixture"}',now() from generate_series(1,6) n;
delete from public.role_assignments where user_id in ('a3100000-0000-4000-8000-000000000001','a3100000-0000-4000-8000-000000000003','a3100000-0000-4000-8000-000000000004','a3100000-0000-4000-8000-000000000005','a3100000-0000-4000-8000-000000000006');
insert into public.role_assignments values('a3100000-0000-4000-8000-000000000001','super_admin'),('a3100000-0000-4000-8000-000000000003','branch'),('a3100000-0000-4000-8000-000000000004','coach'),('a3100000-0000-4000-8000-000000000005','sales'),('a3100000-0000-4000-8000-000000000006','admin');
insert into public.branches(id,slug,name,provisional) values('a3200000-0000-4000-8000-000000000001','invoice-one','Invoice one',false),('a3200000-0000-4000-8000-000000000002','invoice-two','Invoice two',false);
insert into public.branch_sports values('a3200000-0000-4000-8000-000000000001','swimming'),('a3200000-0000-4000-8000-000000000002','swimming');
insert into public.branch_permissions select ('a3100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'a3200000-0000-4000-8000-000000000001' from generate_series(3,5) n;
insert into public.families(id,name) values('a3300000-0000-4000-8000-000000000001','Invoice family'),('a3300000-0000-4000-8000-000000000002','Unrelated family');
insert into public.guardians values('a3300000-0000-4000-8000-000000000001','a3100000-0000-4000-8000-000000000002');
insert into public.family_branches values('a3300000-0000-4000-8000-000000000001','a3200000-0000-4000-8000-000000000001');
insert into public.children(id,family_id,name,reported_age) values('a3400000-0000-4000-8000-000000000001','a3300000-0000-4000-8000-000000000001','Invoice child one',6),('a3400000-0000-4000-8000-000000000002','a3300000-0000-4000-8000-000000000001','Invoice child two',8),('a3400000-0000-4000-8000-000000000003','a3300000-0000-4000-8000-000000000002','Unrelated child',8);
insert into public.child_sports(child_id,sport) select id,'swimming' from public.children where id in ('a3400000-0000-4000-8000-000000000001','a3400000-0000-4000-8000-000000000002','a3400000-0000-4000-8000-000000000003');
insert into public.commercial_packages(id,branch_id,sport,name,price_minor,session_allowance,terms,created_by) values('a3500000-0000-4000-8000-000000000001','a3200000-0000-4000-8000-000000000001','swimming','Synthetic package one',12505,4,'Explicit synthetic price only','a3100000-0000-4000-8000-000000000001'),('a3500000-0000-4000-8000-000000000002','a3200000-0000-4000-8000-000000000002','swimming','Synthetic other branch',10000,4,'Explicit synthetic price only','a3100000-0000-4000-8000-000000000001');

insert into public.leads(id,branch_id,parent_name,mobile) values('a3800000-0000-4000-8000-000000000001','a3200000-0000-4000-8000-000000000001','Synthetic parent','0000000000');
insert into public.trial_enquiries(id,lead_id,child_name,reported_age,sport,experience) values('a3900000-0000-4000-8000-000000000001','a3800000-0000-4000-8000-000000000001','Synthetic child',6,'swimming','beginner');
create function pg_temp.issue_link() returns jsonb language sql as $$select public.registration_link('issue','{"lead_id":"a3800000-0000-4000-8000-000000000001"}')$$;
create function pg_temp.continue_link() returns jsonb language sql as $$select public.registration_link('continue',jsonb_build_object('token',current_setting('test.token'),'child_id','a3400000-0000-4000-8000-000000000001'))$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a3100000-0000-4000-8000-000000000005","role":"authenticated","aal":"aal1"}',true);
select set_config('test.link',pg_temp.issue_link()::text,true);
select set_config('test.token',current_setting('test.link')::jsonb->>'token',true);
select is(length(current_setting('test.token')),64,'Staff gets cryptographically random256bit capability');
select throws_ok($$select * from private.lead_registration_links$$,'42501',null,'Private token registry cannot be read');
select throws_ok($$select pg_temp.continue_link()$$,'42501',null,'Sales cannot consume capability as a guardian');
select set_config('request.jwt.claims','{"sub":"a3100000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select pg_temp.issue_link()$$,'42501',null,'Parent cannot issue staff links');
select throws_ok($$select public.registration_link('continue',jsonb_build_object('token',current_setting('test.token'),'child_id','a3400000-0000-4000-8000-000000000003'))$$,'42501',null,'Token never grants access to unrelated child');
select is(pg_temp.continue_link()->>'id','a3900000-0000-4000-8000-000000000001','Continue preserves original enquiry ID');
select is(pg_temp.continue_link()->>'childId','a3400000-0000-4000-8000-000000000001','Retry preserves selected child');
select is((select count(*)::int from public.guardians where family_id='a3300000-0000-4000-8000-000000000001'),1,'No new guardianship was created');
select is((select count(*)::int from public.trial_enquiries where lead_id='a3800000-0000-4000-8000-000000000001'),1,'No duplicate enquiry');
select throws_ok($$select public.registration_link('continue',jsonb_build_object('token',current_setting('test.token'),'child_id','a3400000-0000-4000-8000-000000000002'))$$,'42501',null,'Consumed capability cannot switch siblings');
reset role;
select is((select token_hash from private.lead_registration_links where id=(current_setting('test.link')::jsonb->>'id')::uuid),encode(extensions.digest(current_setting('test.token'),'sha256'),'hex'),'Only token digest stored');
update private.lead_registration_links set revoked_at=now() where id=(current_setting('test.link')::jsonb->>'id')::uuid;
set local role authenticated;
select throws_ok($$select pg_temp.continue_link()$$,'42501',null,'Revocation checked before replay');
select set_config('request.jwt.claims','{"sub":"a3100000-0000-4000-8000-000000000005","role":"authenticated","aal":"aal1"}',true);
select set_config('test.link',pg_temp.issue_link()::text,true);
select set_config('test.token',current_setting('test.link')::jsonb->>'token',true);
reset role;
update private.lead_registration_links set created_at=now()-interval '3 days',expires_at=now()-interval '1 day' where id=(current_setting('test.link')::jsonb->>'id')::uuid;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a3100000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select pg_temp.continue_link()$$,'42501',null,'Expired capability rejected');
reset role;
select * from finish();rollback;
